import { createHmac } from 'node:crypto';
import {
  VerificationFailure,
  verifyStandardWebhook,
} from './standard-webhooks';

/**
 * The webhook endpoint grants paid access and cannot be authenticated, so this check is
 * the only thing that distinguishes PalPluss from anyone else who has learned the URL.
 *
 * The first vector below was NOT produced by this code. It was generated by a Python
 * implementation transcribed from PalPluss's own sample on
 * https://docs.palpluss.com/guides/webhook-signing, so if the TypeScript here has the
 * construction subtly wrong — the wrong separator, the key used base64 instead of
 * decoded, hex instead of base64 — these fixed bytes will not match and this test fails.
 * Everything after it is generated locally, where the question is behaviour rather than
 * interoperability.
 */

const SECRET = 'whsec_b25nZXJvLXRlc3Qtc2lnbmluZy1rZXktMDEyMzQ1Njc4OQ==';
const ID = 'msg_2x9fQ1aB3cD4eF5gH6iJ7k';
const TIMESTAMP = '1795000000';
const SIGNATURE = 'v1,8LE42e3b6JCs8jGGrBIavMSDbdyCQGh4ozXCxzIuYDI=';
const BODY = Buffer.from(
  '{"event":"transaction.updated","event_type":"transaction.success","transaction":' +
    '{"id":"fa98a577-95ea-4a8f-8467-1fbe74f5d6f4","type":"STK","status":"SUCCESS",' +
    '"amount":500,"currency":"KES","phone_number":"254712345678",' +
    '"external_reference":"ONGB7K2M9XQ4","provider":"m-pesa",' +
    '"mpesa_receipt":"LGR019G3J2","result_code":"0",' +
    '"result_desc":"The service request is processed successfully."}}',
  'utf8',
);

/** The instant the vector's timestamp says the message was sent. */
const AT_SEND_TIME = new Date(Number(TIMESTAMP) * 1000);

const headers = (over: Record<string, string | string[] | undefined> = {}) => ({
  'webhook-id': ID,
  'webhook-timestamp': TIMESTAMP,
  'webhook-signature': SIGNATURE,
  ...over,
});

/** Sign locally, for cases where the vector's fixed bytes are not the point. */
function sign(body: Buffer, id: string, timestamp: string, secret = SECRET): string {
  const key = Buffer.from(secret.replace(/^whsec_/, ''), 'base64');
  return (
    'v1,' +
    createHmac('sha256', key)
      .update(Buffer.concat([Buffer.from(`${id}.${timestamp}.`, 'utf8'), body]))
      .digest('base64')
  );
}

describe('verifyStandardWebhook', () => {
  it('accepts a signature generated by an independent implementation', () => {
    expect(verifyStandardWebhook(BODY, headers(), SECRET, AT_SEND_TIME)).toEqual({
      ok: true,
    });
  });

  it('rejects a body altered by a single byte', () => {
    // The amount is what decides whether a subscription is granted. Changing 500 to 900
    // while keeping the signature is precisely the attack this exists to stop.
    const tampered = Buffer.from(
      BODY.toString('utf8').replace('"amount":500', '"amount":900'),
      'utf8',
    );

    expect(verifyStandardWebhook(tampered, headers(), SECRET, AT_SEND_TIME)).toEqual({
      ok: false,
      reason: VerificationFailure.NO_MATCHING_SIGNATURE,
    });
  });

  it('rejects a valid signature replayed under a different message id', () => {
    expect(
      verifyStandardWebhook(BODY, headers({ 'webhook-id': 'msg_other' }), SECRET, AT_SEND_TIME),
    ).toEqual({ ok: false, reason: VerificationFailure.NO_MATCHING_SIGNATURE });
  });

  it('rejects a signature made with a different secret', () => {
    const other = 'whsec_' + Buffer.from('a-completely-different-key').toString('base64');
    expect(
      verifyStandardWebhook(BODY, headers({ 'webhook-signature': sign(BODY, ID, TIMESTAMP, other) }), SECRET, AT_SEND_TIME),
    ).toEqual({ ok: false, reason: VerificationFailure.NO_MATCHING_SIGNATURE });
  });

  it('rejects a replay from outside the tolerance window', () => {
    const sixMinutesLater = new Date(AT_SEND_TIME.getTime() + 6 * 60 * 1000);
    expect(verifyStandardWebhook(BODY, headers(), SECRET, sixMinutesLater)).toEqual({
      ok: false,
      reason: VerificationFailure.TIMESTAMP_OUT_OF_TOLERANCE,
    });
  });

  it('accepts a delivery inside the tolerance window', () => {
    const fourMinutesLater = new Date(AT_SEND_TIME.getTime() + 4 * 60 * 1000);
    expect(verifyStandardWebhook(BODY, headers(), SECRET, fourMinutesLater)).toEqual({
      ok: true,
    });
  });

  it('rejects a future-dated timestamp just as firmly as an old one', () => {
    const tenMinutesEarlier = new Date(AT_SEND_TIME.getTime() - 10 * 60 * 1000);
    expect(verifyStandardWebhook(BODY, headers(), SECRET, tenMinutesEarlier)).toEqual({
      ok: false,
      reason: VerificationFailure.TIMESTAMP_OUT_OF_TOLERANCE,
    });
  });

  it.each([
    ['not a number', 'yesterday'],
    ['padded', ' 1795000000 '],
    ['fractional', '1795000000.5'],
  ])('rejects a %s timestamp rather than coercing it', (_label, timestamp) => {
    // Number(' 12 ') is 12 and Number('12.5') is 12.5. Either would be compared
    // against the clock, so without the pattern check a malformed header could still
    // land inside the tolerance window.
    expect(
      verifyStandardWebhook(BODY, headers({ 'webhook-timestamp': timestamp }), SECRET, AT_SEND_TIME),
    ).toEqual({ ok: false, reason: VerificationFailure.BAD_TIMESTAMP });
  });

  it.each(['webhook-id', 'webhook-timestamp', 'webhook-signature'])(
    'rejects a delivery whose %s is absent or empty',
    (header) => {
      // An empty value is treated as absent, not as a value to parse. Number('') is 0,
      // which is a real unix time and would be compared against the clock rather than
      // refused, so the emptiness has to be caught before the timestamp check.
      for (const value of [undefined, '']) {
        expect(
          verifyStandardWebhook(BODY, headers({ [header]: value }), SECRET, AT_SEND_TIME),
        ).toEqual({ ok: false, reason: VerificationFailure.MISSING_HEADERS });
      }
    },
  );

  it('rejects a repeated header rather than picking one', () => {
    // Node surfaces a duplicated header as an array. Taking the first would let a
    // forger send a valid pair plus their own.
    expect(
      verifyStandardWebhook(BODY, headers({ 'webhook-id': [ID, 'msg_evil'] }), SECRET, AT_SEND_TIME),
    ).toEqual({ ok: false, reason: VerificationFailure.MISSING_HEADERS });
  });

  it('accepts either signature during a secret rotation', () => {
    const rotatedOut = 'whsec_' + Buffer.from('the-previous-signing-key').toString('base64');
    const pair = `${sign(BODY, ID, TIMESTAMP, rotatedOut)} ${SIGNATURE}`;

    // PalPluss sends both for 24 hours after a rotation. A server holding either
    // secret must accept the delivery, whichever position its signature is in.
    expect(
      verifyStandardWebhook(BODY, headers({ 'webhook-signature': pair }), SECRET, AT_SEND_TIME),
    ).toEqual({ ok: true });
    expect(
      verifyStandardWebhook(BODY, headers({ 'webhook-signature': pair }), rotatedOut, AT_SEND_TIME),
    ).toEqual({ ok: true });
  });

  it('ignores signature entries with an unknown version prefix', () => {
    const v2 = SIGNATURE.replace('v1,', 'v2,');
    expect(
      verifyStandardWebhook(BODY, headers({ 'webhook-signature': v2 }), SECRET, AT_SEND_TIME),
    ).toEqual({ ok: false, reason: VerificationFailure.NO_MATCHING_SIGNATURE });
  });

  it('rejects a malformed signature entry without throwing', () => {
    for (const malformed of ['v1', 'garbage', ',', 'v1,', 'v1,!!!not base64!!!']) {
      expect(
        verifyStandardWebhook(BODY, headers({ 'webhook-signature': malformed }), SECRET, AT_SEND_TIME),
      ).toEqual({ ok: false, reason: VerificationFailure.NO_MATCHING_SIGNATURE });
    }
  });

  it('rejects a secret that decodes to nothing instead of trusting an empty key', () => {
    // An empty key still produces a valid HMAC, so a secret of "whsec_" would verify
    // anything an attacker signed with an empty key. That must fail closed.
    for (const unusable of ['whsec_', '', 'whsec_!!!!']) {
      const verdict = verifyStandardWebhook(BODY, headers(), unusable, AT_SEND_TIME);
      expect(verdict.ok).toBe(false);
      if (!verdict.ok) {
        expect(verdict.reason).toBe(VerificationFailure.MALFORMED_SECRET);
      }
    }
  });

  it('accepts a secret given without the whsec_ prefix', () => {
    const bare = SECRET.replace('whsec_', '');
    expect(verifyStandardWebhook(BODY, headers(), bare, AT_SEND_TIME)).toEqual({ ok: true });
  });

  it('verifies the exact bytes, not a re-serialised object', () => {
    // JSON.parse then JSON.stringify reorders nothing here but does drop the original
    // formatting; this proves the difference is fatal, which is why the controller
    // works from req.rawBody.
    const reserialised = Buffer.from(
      JSON.stringify(JSON.parse(BODY.toString('utf8')), null, 2),
      'utf8',
    );
    expect(
      verifyStandardWebhook(reserialised, headers(), SECRET, AT_SEND_TIME),
    ).toEqual({ ok: false, reason: VerificationFailure.NO_MATCHING_SIGNATURE });
  });
});
